//
// Health-risk example — encrypt one patient (patient side, CKKS)
//
// Checks the inputs against the supported range, does the logarithms and slot
// placement in the clear, then encrypts. Out-of-range input is refused before
// anything is encrypted (exit code 3), so no unsupported value reaches the
// server's risk curve.
//
// Usage: ./health_risk_encrypt <client_home> <out.bin> <sex m|f> <age> <bmi> <sbp>
//                              <bp_treated 0|1> <smoker 0|1> <diabetic 0|1>

#include "openfhe.h"

#include "ciphertext-ser.h"
#include "cryptocontext-ser.h"
#include "key/key-ser.h"
#include "scheme/ckksrns/ckksrns-ser.h"

#include "common.hpp"

using namespace lbcrypto;
using namespace health_risk;

int main(int argc, char* argv[]) {
    if (argc != 10) {
        std::cerr << "Usage: " << argv[0]
                  << " <client_home> <out.bin> <m|f> <age> <bmi> <sbp> <bp_treated> <smoker> <diabetic>"
                  << std::endl;
        return 2;
    }
    const std::string home = argv[1], out = argv[2], sex = argv[3];
    if (sex != "m" && sex != "f") {
        std::cerr << "[REFUSED] sex must be m or f" << std::endl;
        return 3;
    }
    Patient p{sex == "m", std::stod(argv[4]), std::stod(argv[5]), std::stod(argv[6]),
              std::stoi(argv[7]), std::stoi(argv[8]), std::stoi(argv[9])};
    if (auto why = out_of_range(p); !why.empty()) {
        std::cerr << "[REFUSED] " << why << std::endl;
        return 3;
    }

    CryptoContext<DCRTPoly> cc;
    if (!Serial::DeserializeFromFile(home + "/cc.bin", cc, SerType::BINARY))
        throw std::runtime_error("Failed to load crypto context");
    PublicKey<DCRTPoly> pk;
    if (!Serial::DeserializeFromFile(home + "/pk.bin", pk, SerType::BINARY))
        throw std::runtime_error("Failed to load public key");

    auto ct = cc->Encrypt(pk, cc->MakeCKKSPackedPlaintext(pack(p)));
    if (!Serial::SerializeToFile(out, ct, SerType::BINARY))
        throw std::runtime_error("Failed to serialize ciphertext");
    return 0;
}
